(()=>{const T=THREE,cache=new Map();function texture(type){if(cache.has(type))return cache.get(type);const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');g.fillStyle=type==='grass'?'#8a9270':type==='roof'?'#b4b7b4':'#acaca7';g.fillRect(0,0,256,256);let seed=1;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}for(let i=0;i<16000;i++){const v=Math.floor(90+rand()*120);g.fillStyle=`rgba(${v},${v},${v},.22)`;g.fillRect(rand()*256,rand()*256,type==='grass'?1:2,type==='grass'?3:1);}if(type==='leaves')for(let i=0;i<500;i++){g.fillStyle=i%2?'#ffffff35':'#152b1a50';g.beginPath();g.ellipse(rand()*256,rand()*256,3+rand()*7,2+rand()*4,rand()*6,0,7);g.fill();}if(type==='roof')for(let i=0;i<256;i+=16){g.fillStyle='#313b4260';g.fillRect(i,0,3,256);g.fillStyle='#ffffff60';g.fillRect(i+3,0,1,256);}const tex=new T.CanvasTexture(c);tex.wrapS=tex.wrapT=T.RepeatWrapping;tex.repeat.set(type==='leaves'?1:type==='roof'?2:32,type==='leaves'?1:type==='roof'?2:32);tex.colorSpace=T.SRGBColorSpace;cache.set(type,tex);return tex;}
function sign(kind){if(cache.has(kind))return cache.get(kind);if(window.DriveSignImages?.[kind]&&typeof Image!=='undefined'){const c=document.createElement('canvas');c.width=c.height=512;const g=c.getContext('2d'),tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;cache.set(kind,tex);const img=new Image();img.onload=()=>{const ratio=Math.min(480/img.width,480/img.height),w=img.width*ratio,h=img.height*ratio;g.clearRect(0,0,512,512);g.drawImage(img,(512-w)/2,(512-h)/2,w,h);tex.needsUpdate=true;};img.src=DriveSignImages[kind];return tex;}const c=document.createElement('canvas');c.width=c.height=256;const g=c.getContext('2d');g.lineJoin='round';g.lineWidth=14;function poly(n,r,offset){g.beginPath();for(let i=0;i<n;i++){const a=offset+i*Math.PI*2/n;g.lineTo(128+Math.cos(a)*r,128+Math.sin(a)*r);}g.closePath();}function circle(){g.beginPath();g.arc(128,128,105,0,Math.PI*2);}g.strokeStyle='#f6f3e5';g.fillStyle='#d1322d';if(kind==='stop'){poly(8,112,Math.PI/8);g.fill();g.stroke();g.fillStyle='white';g.font='bold 65px Arial';g.textAlign='center';g.fillText('STOP',128,151);}else if(kind==='yield'){poly(3,120,Math.PI/2);g.fillStyle='#fff8e6';g.fill();g.strokeStyle='#cf302c';g.stroke();}else if(kind==='priority'){poly(4,112,0);g.fillStyle='#f3ca42';g.fill();g.stroke();}else if(kind.startsWith('limit')||kind==='noParking'||kind==='noStopping'){circle();g.fillStyle=kind.startsWith('limit')?'#fff9ed':'#17589e';g.fill();g.strokeStyle='#d53230';g.stroke();if(kind.startsWith('limit')){g.fillStyle='#141b20';g.font='bold 98px Arial';g.textAlign='center';g.fillText(kind.slice(5),128,162);}else{g.beginPath();g.moveTo(58,58);g.lineTo(198,198);if(kind==='noStopping'){g.moveTo(58,198);g.lineTo(198,58);}g.stroke();}}else{g.fillStyle='#17639d';g.fillRect(19,19,218,218);g.strokeRect(19,19,218,218);g.fillStyle='white';g.textAlign='center';g.font=kind==='busStop'?'bold 65px Arial':'bold 120px Arial';g.fillText(kind==='parking'?'P':kind==='roundabout'?'↻':kind==='busStop'?'BUS':'△',128,170);if(kind==='crossing'){g.fillStyle='#182332';g.beginPath();g.arc(128,110,10,0,7);g.fill();g.fillRect(122,122,12,35);g.strokeStyle='#182332';g.lineWidth=8;g.beginPath();g.moveTo(128,140);g.lineTo(111,174);g.moveTo(128,140);g.lineTo(145,174);g.stroke();}}const tex=new T.CanvasTexture(c);tex.colorSpace=T.SRGBColorSpace;cache.set(kind,tex);return tex;}
function map(canvas,s,whole){const g=canvas.getContext('2d'),n=320,p=s.player;g.clearRect(0,0,n,n);g.fillStyle='#19291f';g.fillRect(0,0,n,n);const scale=whole?2.3:7,cx=whole?48:p.x,cz=whole?56:p.z;const xy=(x,z)=>[160+(x-cx)*scale,160+(z-cz)*scale];g.save();g.beginPath();g.rect(8,24,304,265);g.clip();g.shadowColor='#83e6ed';g.shadowBlur=7;g.strokeStyle='#73abb0';g.lineWidth=1.2*scale;for(const a of DriveWorld.AXES){g.beginPath();g.moveTo(...xy(-8,a));g.lineTo(...xy(104,a));g.moveTo(...xy(a,8));if(a===8){g.lineTo(...xy(a,26));g.moveTo(...xy(a,38));}g.lineTo(...xy(a,104));g.stroke();}g.shadowBlur=0;g.fillStyle='#67736c';const campus=xy(-5,26);g.fillRect(campus[0],campus[1],26*scale,12*scale);g.fillStyle='#d9d9b7';g.font='bold 10px Arial';g.fillText('POLIGON AUTO',campus[0]+13*scale,campus[1]+12);if(window.DriveTraining)for(const t of DriveTraining.tasks){const [tx,ty]=xy(t.x,t.z);g.fillStyle='#9ee2b6';g.fillRect(tx-2,ty-2,4,4);}g.fillStyle='#243b34';for(let x=10;x<103;x+=16)for(let z=10;z<103;z+=16){const q=xy(x,z);g.fillRect(q[0],q[1],12*scale,12*scale);}const target=window.DriveSimulation?.objective(s)?.target||DriveWorld.landmarks.find(l=>l.id===({pickup:'pickup',dropoff:'dropoff',park:'parking'}[s.mission?.phase]));const marks=[...DriveCareer.places.map((l,i)=>({...l,label:['ȘCOALĂ','BENZINĂ','AUTO','VOPSEA','POLIGON'][i]})),...DriveWorld.landmarks.map(l=>({...l,label:l.kind==='pickup'?'PASAGER':l.kind==='dropoff'?'DESTINAȚIE':l.kind==='parking'?'P':'BUS'}))];for(const l of marks){const [x,y]=xy(l.x,l.z);g.fillStyle=l===target?'#ffe297':'#9ddbd8';g.beginPath();g.arc(x,y,4,0,7);g.fill();g.font='bold 11px Arial';g.textAlign='center';g.strokeStyle='#12231c';g.lineWidth=4;g.strokeText(l.label,x,y-9);g.fillText(l.label,x,y-9);}if(target){const [x,y]=xy(target.x,target.z);g.strokeStyle='#ffd37b';g.lineWidth=3;g.beginPath();g.arc(x,y,9,0,7);g.stroke();}if(window.DriveNavigator){const path=DriveNavigator.path();if(path.length){g.strokeStyle='#f5c366';g.lineWidth=3;g.beginPath();g.moveTo(...xy(p.x,p.z));for(const n of path)g.lineTo(...xy(n.x,n.z));const d=DriveNavigator.destination();if(d)g.lineTo(...xy(d.x,d.z));g.stroke();}}const [px,py]=xy(p.x,p.z);g.save();g.translate(px,py);g.rotate(p.angle+Math.PI/2);g.fillStyle='#fff2cf';g.beginPath();g.moveTo(0,-9);g.lineTo(6,7);g.lineTo(0,4);g.lineTo(-6,7);g.closePath();g.fill();g.restore();g.restore();g.fillStyle='#ede9d6';g.font='bold 13px Arial';g.textAlign='left';g.fillText('N ↑',12,18);g.textAlign='right';g.fillText(whole?'ORAȘ · CLICK PENTRU ZOOM':'APROAPE · CLICK PENTRU ORAȘ',308,307);}
window.DriveVisuals={texture,sign,map};})();
